/* Edição em colunas dos cadastros. Mantém as mesmas validações dos formulários. */
(()=>{'use strict';const D=window.Obras,M=window.EngefexManager,h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fields={projects:'code name client location value start referenceDays owner state',activities:'name unit quantity executed start finish actualFinish responsible nextAction',stages:'code name parent source',budgetItems:'code name stage unit quantity unitPrice sale executed laborUnit materialUnit equipmentUnit',budgetStages:'code name parent sale saleMode source',tasks:'title activity date priority responsible status nextAction',issues:'title category priority responsibleId due status action resolution',checklists:'stage phase title responsible due status evidence',materials:'name activity unit planned opening onOrder needDate leadDays responsible status',stockMoves:'material activity date type quantity document reason',costs:'stage supplier description document date category amount incurred paid paymentDiscount paymentAddition due paidDate note',quotes:'stage supplier description category amount date note',measurements:'number activity quantity status date submitted approved expected evidence note',receipts:'number date amount note',teams:'name specialty people responsible contact equipment',diary:'date activity description quantity hours conditions materials equipment inspections interference instructions nextDay',documents:'name reading sourcePath text',facts:'title value basis source'};
let bridge=null,active=null,dirty=false;
function specs(kind,row,schema){let selected=fields[kind]?.split(' ');if(!selected)throw Error('Cadastro sem edição em planilha.');let all=schema(kind,row);let result=selected.map(key=>all.find(f=>f.key===key)).filter(Boolean);if(['stages','budgetStages'].includes(kind))result.push(...Array.from({length:12},(_,i)=>({key:'month'+i,label:'M'+(i+1)+' (%)',type:'number',month:i})),{key:'reprogrammingNote',label:'Motivo da reprogramação',type:'text'});return result}
function valueOf(f,value){if(f.type==='number')return window.EngefexGrid.number(value,!!f.nullable);if(f.type==='date')return window.EngefexGrid.date(value);return String(value??'').trim()}
function changePrice(record,before){if(Number(record.sale)!==Number(before.sale))record.unitPrice=Number(record.quantity)?Number(record.sale)/Number(record.quantity):0;else if(Number(record.quantity)!==Number(before.quantity)||Number(record.unitPrice)!==Number(before.unitPrice))record.sale=Number(record.quantity)*Number(record.unitPrice)}
function apply(kind,state,draft,schema){let next=D.clone(state),ordered=draft.map((row,i)=>({row,i}));if(kind==='diary')ordered.sort((x,y)=>{let delta=r=>{try{return window.EngefexGrid.number(r.quantity||0)-Number(state.diary.find(d=>d.id===r.id)?.quantity||0)}catch{return 0}};return delta(x.row)-delta(y.row)});for(let {row,i}of ordered){try{let before=state[kind].find(r=>r.id===row.id);if(!before)throw Error('Registro não encontrado.');let record=D.clone(before);for(let f of specs(kind,row,schema)){if(f.month===undefined&&!Object.prototype.hasOwnProperty.call(row,f.key))continue;if(f.month!==undefined){record.months=record.months||Array(12).fill(0);let percent=row[f.key]??Number(before.months?.[f.month]||0)*100,month=valueOf(f,percent)/100;if(Math.abs(Number(record.months[f.month])-month)>1e-12)record.months[f.month]=month;}else record[f.key]=valueOf(f,row[f.key]);}if(['stages','budgetStages'].includes(kind)&&JSON.stringify(record.months)!==JSON.stringify(before.months)){if(Math.abs(record.months.reduce((a,b)=>a+b,0)-1)>.00001)throw Error('A distribuição mensal precisa somar 100%.');if(!record.reprogrammingNote)throw Error('Informe o motivo da reprogramação.');}if(kind==='budgetItems')changePrice(record,before);if(JSON.stringify(record)===JSON.stringify(before))continue;if(kind==='projects'){if(!record.name)throw Error('Informe o nome da obra.');record.code=record.code||M.nextProjectCode(next.projects);if(next.projects.some(p=>p.id!==record.id&&String(p.code).toUpperCase()===record.code.toUpperCase()))throw Error('Código da obra já usado.');}if(['projects','stages','budgetStages','documents','facts'].includes(kind))next=M.save(next,kind,record);else next=D.saveRecord(next,kind,record)}catch(e){throw Error('Linha '+(i+1)+': '+e.message)}}return M.reconcile(next)}
function render(kind,state,project,schema){let records=(kind==='issues'&&window.EngefexAlerts&&window.EngefexCloud?.currentUser?window.EngefexAlerts.personal(state,window.EngefexCloud.currentUser,project):state[kind]).filter(r=>kind==='projects'?(project==='all'||r.id===project):kind==='facts'||project==='all'||r.project===project||r.project==='Geral');let sample=records[0]||{...M.defaults(kind,project),id:'',project};active={kind,snapshot:D.clone(state),draft:records.map(r=>({...D.clone(r),...Object.fromEntries(Array.from({length:12},(_,i)=>['month'+i,Number(r.months?.[i]||0)*100]))})),schema,cols:specs(kind,sample,schema)};dirty=false;let cell=(r,i,f)=>{let a='data-record-row="'+i+'" data-record-key="'+h(f.key)+'" aria-label="Linha '+(i+1)+' · '+h(f.label)+'"',value=r[f.key]??'';if(f.type==='select')return '<select '+a+'><option value="">Selecionar…</option>'+(f.options||[]).map(([v,t])=>'<option value="'+h(v)+'" '+(String(value)===String(v)?'selected':'')+'>'+h(t)+'</option>').join('')+'</select>';if(f.type==='textarea')return '<textarea '+a+' rows="1">'+h(value)+'</textarea>';return '<input '+a+' '+(f.type==='number'?'inputmode="decimal"':'')+' value="'+h(value)+'">'};return '<section class="batch-panel"><div class="actions"><button type="button" class="button primary" id="recordsSave">Salvar alterações</button><button type="button" class="button secondary" id="recordsDiscard">Descartar alterações</button><span id="recordsStatus" role="status">Nenhuma alteração pendente.</span></div><p class="section-note">Edite nas colunas ou cole células do Excel. Tab avança e Enter desce. Salvar alterações grava o lote inteiro; os dados só mudam depois de salvar. Use o formulário individual para anexos e campos complementares.</p><p id="recordsError" class="notice red-text" role="alert" hidden></p><div class="table-wrap records-wrap"><table class="records-sheet"><thead><tr><th>Linha</th>'+active.cols.map(f=>'<th>'+h(f.label)+'</th>').join('')+'</tr></thead><tbody>'+records.map((r,i)=>{let rowSpecs=specs(kind,r,schema);return '<tr><th scope="row">'+(i+1)+'</th>'+active.cols.map(col=>'<td>'+cell(active.draft[i],i,rowSpecs.find(f=>f.key===col.key)||col)+'</td>').join('')+'</tr>'}).join('')+'</tbody></table></div>'+(records.length?'':'<p class="empty">Nenhum registro cadastrado nesta obra.</p>')+'</section>'}
function mark(){dirty=true;document.getElementById('recordsStatus').textContent='Alterações pendentes · clique em Salvar alterações.'}
function update(row,key,value){let r=active.draft[row];r[key]=value;if(active.kind==='budgetItems'&&['quantity','unitPrice','sale'].includes(key)){try{let n=window.EngefexGrid.number;if(key==='sale')r.unitPrice=n(r.quantity)?n(value)/n(r.quantity):0;else r.sale=n(r.quantity)*n(r.unitPrice);let changed=key==='sale'?'unitPrice':'sale',input=document.querySelector('[data-record-row="'+row+'"][data-record-key="'+changed+'"]');if(input)input.value=r[changed]}catch{}}mark()}
function bind(){if(!document.getElementById('recordsSave'))return;for(let input of document.querySelectorAll('[data-record-row]')){let read=()=>update(Number(input.dataset.recordRow),input.dataset.recordKey,input.value);input.addEventListener('input',read);input.addEventListener('change',read);input.addEventListener('keydown',e=>{if(e.key==='Enter'&&input.tagName!=='TEXTAREA'){e.preventDefault();document.querySelector('[data-record-row="'+(Number(input.dataset.recordRow)+1)+'"][data-record-key="'+input.dataset.recordKey+'"]')?.focus()}});input.addEventListener('paste',e=>{let text=e.clipboardData?.getData('text/plain');if(!text||(!text.includes('\t')&&(!text.includes('\n')||input.tagName==='TEXTAREA')))return;e.preventDefault();let rows=text.replace(/\r/g,'').replace(/\n$/,'').split('\n').map(r=>r.split('\t')),start=Number(input.dataset.recordRow),col=active.cols.findIndex(f=>f.key===input.dataset.recordKey),writes=[];try{if(start+rows.length>active.draft.length)throw Error('O bloco excede as linhas disponíveis.');rows.forEach((line,i)=>line.forEach((value,j)=>{let f=active.cols[col+j];if(!f)throw Error('O bloco excede as colunas disponíveis.');let target=document.querySelector('[data-record-row="'+(start+i)+'"][data-record-key="'+f.key+'"]');if(target.tagName==='SELECT'&&value){let matches=[...target.options].filter(o=>o.value===value||o.textContent.trim()===value.trim());if(matches.length!==1)throw Error('Seleção não reconhecida: '+value);value=matches[0].value}writes.push({target,row:start+i,key:f.key,value})}));for(let w of writes){w.target.value=w.value;update(w.row,w.key,w.value)}}catch(err){let error=document.getElementById('recordsError');error.hidden=false;error.textContent=err.message+' Nenhuma célula foi colada.'}})}document.getElementById('recordsSave').onclick=async()=>{try{if(JSON.stringify(bridge.getState())!==JSON.stringify(active.snapshot))throw Error('Os dados mudaram. Descarte a edição e abra a grade novamente.');let next=apply(active.kind,active.snapshot,active.draft,active.schema);if(await bridge.save(next)===false)throw Error('O banco não confirmou o salvamento. Exporte backup antes de recuperar.');dirty=false;bridge.render()}catch(e){let error=document.getElementById('recordsError');error.hidden=false;error.textContent=e.message}};document.getElementById('recordsDiscard').onclick=()=>{if(!dirty||confirm('Descartar as alterações ainda não salvas?')){dirty=false;bridge.render()}}}
window.EngefexRecordsGrid={render,bind,apply,specs,isDirty:()=>dirty,init(api){bridge=api;window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});document.addEventListener('click',e=>{if(dirty&&e.target.closest('nav a,[data-action],[data-tab],[data-edit],[data-remove]')){if(!confirm('Há alterações em colunas sem salvar. Descartar e continuar?')){e.preventDefault();e.stopImmediatePropagation()}else dirty=false}},true);document.getElementById('project')?.addEventListener('change',e=>{if(dirty&&!confirm('Descartar a edição para trocar de obra?')){e.stopImmediatePropagation();e.target.value=api.getProject()}else dirty=false},true)}};
})();

